const _ecoOvt = (dier, deel, skin) => ({ skin, lagen: ECOKLEIN_OVERTREK[dier][deel].map(l => ({ c: l.c, p: l.p })) });
// lijf = romp + nek + kop als één overgetrokken stuk: nek-gewichten langs nekBasis->kop, het rompaandeel verdeeld over rompV/M/A
const _ecoLijfGew = (k0 = 0.3, k1 = 1.0, mond = null) => ({ J, projectie, sstep, GEW }) => (v) => { const u = projectie(v, [J.nekBasis, J.kop]); const wa = 1 - sstep((u + k0) / k1); let wk = sstep((u - 0.6) / 0.45);
  let wj = 0; if (mond) { const [x0, y0, x1, y1] = mond; if (v[0] > x0) { const ym = y0 + (y1 - y0) * Math.min(1, (v[0] - x0) / (x1 - x0)); wj = sstep((v[1] - ym) / 0.8) * sstep((v[0] - x0) / 2.5) * wk; wk -= wj; } }
  const out = GEW.romp(v).map(([b, w]) => [b, w * wa]); out.push(['nek', Math.max(0, 1 - wa - wk - wj)], ['kop', wk]); if (wj > 0) out.push(['kaak', wj]); return out; };
